from collections import Counter
def transform(g):
    h,w=len(g),len(g[0])
    c=Counter(x for r in g for x in r)
    bg=c.most_common(1)[0][0]
    # count non-bg cells per position; markers are isolated single cells of one color, pattern is the rest
    cells=[(r,val) for r,row in enumerate(g) for c2,val in enumerate(row) if val!=bg]
    cc=Counter(v for _,v in cells)
    marker=cc.most_common()[-1][0]  # least common non-bg? demo: 3 appears 3x, others more
    # better: marker color = color whose cells are all isolated
    pos={}
    for r,v in cells: pos.setdefault(v,[]).append(r)
    # compute positions
    positions={}
    for r,row in enumerate(g):
        for c2,v in enumerate(row):
            if v!=bg: positions.setdefault(v,[]).append((r,c2))
    def isolated(v):
        ps=positions[v]
        return all(all(abs(r1-r2)+abs(c1-c2)>1 for (r2,c2) in ps if (r2,c2)!=(r1,c1)) for (r1,c1) in ps)
    marker=[v for v in positions if v!=bg and isolated(v)][0]
    patcells=[(r,c2) for r,row in enumerate(g) for c2,v in enumerate(row) if v not in (bg,marker)]
    r0=min(r for r,_ in patcells); r1=max(r for r,_ in patcells)
    c0=min(c for _,c in patcells); c1=max(c for _,c in patcells)
    P=[[g[r][c2] for c2 in range(c0,c1+1)] for r in range(r0,r1+1)]
    ph,pw=len(P),len(P[0])
    out=[row[:] for row in g]
    for (r,c2) in positions[marker]:
        for i in range(ph):
            for j in range(pw):
                rr,cc2=r-ph//2+i, c2-pw//2+j
                if 0<=rr<h and 0<=cc2<w: out[rr][cc2]=P[i][j]
    return out

